// layerWeights is where one layer's weights sit in the arenas.
type layerWeights struct {
	// fp32 arena: the four norms.
	attnNorm, ffnNorm uint32
	qNorm, kNorm      uint32
	// fp16 bank and the offset of each projection inside it, in halves.
