	raw := g.hbuf.ReadUint16At(int(off), (g.rows-1)*lda+cols)
	out := NewMat(g.rows, cols)
	for r := 0; r < g.rows; r++ {
		row, src := out.Row(r), raw[r*lda:]
		for c := 0; c < cols; c++ {
			row[c] = safetensors.F16ToF32(src[c])
