// budget and reads the same arena at 15 GB/s, where 63 MB is 6.5 ms. See
// cmd/bus and research/stage-9-head-and-tail.md.
func (g *GPUStack) Run(sel []int) error {
	sel, err := g.selection(sel)
	if err != nil {
		return err
	}
	for _, i := range sel {
		d, _, err := g.blockGraph(i)
		if err != nil {
