// TestGPUGEMMLadder times the whole encoder once per projection kernel, which
// is what PlanFor's boundaries are read off.
//
// It is a ladder over the *graph* and not over a GEMM in isolation, which is
// the point: results/shapes.csv measures one shape at a time with its operands
// hot, and this runs 1.15 GB of weights past the cores once per clip, so the
// rung that wins here is allowed to disagree with the rung that wins there.
func TestGPUGEMMLadder(t *testing.T) {
	if testing.Short() {
		t.Skip("one run of the whole encoder per rung")
	}
	g, _, x, valid, done := newTestEncoder(t, controls{})
	defer done()

	type row struct {
		kernel GEMMKernel
		d      time.Duration
		m      int
	}
	var rows []row
	best := time.Duration(math.MaxInt64)
	for _, k := range GEMMKernels() {
		if err := g.SetPlan(UniformGEMMPlan(k)); err != nil {
			t.Fatalf("%s: %v", k, err)
		}
		if err := g.Upload(x, valid); err != nil {
			t.Fatalf("%s: %v", k, err)
		}
		var d time.Duration
		for rep := 0; rep < 3; rep++ {
			if err := g.Upload(x, valid); err != nil {
				t.Fatal(err)
			}
			start := time.Now()
			if err := g.Run(); err != nil {
				t.Fatalf("%s: %v", k, err)
			}
			if rep == 0 || time.Since(start) < d {
				d = time.Since(start)
			}
		}
		rows = append(rows, row{k, d, g.RowsPadded()})
		best = min(best, d)
	}
	for _, r := range rows {
		t.Logf("%-20s M=%-4d %7.2f ms  %.2fx", r.kernel, r.m, float64(r.d.Microseconds())/1e3, float64(r.d)/float64(best))
	}
}
